static const IconData *find_icon(const char *name) {
    for(const auto &icon : ICONS) if(std::strcmp(icon.name, name) == 0) return &icon;
    return nullptr;
}

lv_obj_t *make_lucide_icon(lv_obj_t *parent, const char *name, int size, lv_color_t color) {
    lv_obj_t *wrap = lv_obj_create(parent);
    lv_obj_clear_flag(wrap, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(wrap, size, size);
    lv_obj_set_style_bg_opa(wrap, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(wrap, 0, 0);
    lv_obj_set_style_pad_all(wrap, 0, 0);
    const IconData *icon = find_icon(name);
    if(!icon) return wrap;
    const float scale = size / 24.0f;
    static lv_style_t style;
    static bool style_init = false;
    if(!style_init) { lv_style_init(&style); lv_style_set_line_width(&style, 2); lv_style_set_line_rounded(&style, true); style_init = true; }
    for(uint16_t p = 0; p < icon->path_count; ++p) {
        lv_obj_t *line = lv_line_create(wrap);
        lv_obj_add_style(line, &style, 0);
        lv_obj_set_style_line_color(line, color, 0);
        lv_obj_set_style_line_width(line, size >= 44 ? 3 : 2, 0);
        lv_point_precise_t *pts = static_cast<lv_point_precise_t *>(lv_malloc(sizeof(lv_point_precise_t) * icon->paths[p].count));
        if(!pts) { lv_obj_delete(line); continue; }
        for(uint16_t i = 0; i < icon->paths[p].count; ++i) { pts[i].x = static_cast<lv_coord_t>(icon->paths[p].points[i].x * scale); pts[i].y = static_cast<lv_coord_t>(icon->paths[p].points[i].y * scale); }
        lv_line_set_points(line, pts, icon->paths[p].count);
        lv_obj_add_event_cb(line, [](lv_event_t *e) { lv_free(lv_event_get_user_data(e)); }, LV_EVENT_DELETE, pts);
    }
    return wrap;
}

